INSERT INTO setmealdetailed(smId,ciId) SELECT s.smId,c.ciId FROM setmeal s JOIN checkitem c ON c.ciName='血脂检查' WHERE NOT EXISTS(SELECT 1 FROM setmealdetailed sd WHERE sd.smId=s.smId AND sd.ciId=c.ciId);
